def evaluate(current_reputation, observation, my_history, round_num):
    alpha = 0.15
    delta = 0.0
    if observation['action'] == 'cooperate':
        delta = 0.9
        if current_reputation < -0.9:
            delta += 0.25
        if round_num < 3:
            delta += 0.2
        if my_history:
            own_coop = sum(1 for e in my_history if e.get('action') == 'cooperate')
            if own_coop / len(my_history) > 0.7:
                delta += 0.1
    else:
        delta = -1.1
        if round_num > 5 and current_reputation > 0.5:
            delta = -1.5
        if my_history:
            own_coop = sum(1 for e in my_history if e.get('action') == 'cooperate')
            if own_coop / len(my_history) > 0.6:
                delta -= 0.2
    new_rep = current_reputation + alpha * delta
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    if not my_history:
        return True
    coop_count = sum(1 for e in my_history if e.get('action') == 'cooperate')
    total = len(my_history)
    own_ratio = coop_count / total
    threshold = -0.3 + 0.4 * own_ratio
    if round_num < 3:
        threshold -= 0.4
    if round_num > 10:
        threshold += 0.2
    if own_ratio < 0.2 and round_num > 5:
        threshold = 0.6
    if own_ratio > 0.8:
        threshold -= 0.2
    return recipient_reputation > threshold
